fun main() {
    val s = readLine()!!.trim()
    if (s.isEmpty()) {
        println(0)
        return
    }
    var count = 0
    var prev = s[0]
    var runLength = 1
    for (i in 1 until s.length) {
        if (s[i] == prev) {
            runLength++
        } else {
            if (runLength % 2 == 0) {
                count++
            }
            prev = s[i]
            runLength = 1
        }
    }
    if (runLength % 2 == 0) {
        count++
    }
    println(count)
}
